import copy, re
import docx
from docx.shared import RGBColor, Pt
from docx.oxml.ns import qn
from docx.oxml import OxmlElement

RED = RGBColor(0xC0, 0x00, 0x00)
AUTHOR = "Aldgate & Whitmore LLP (IP Counsel)"
INITIALS = "A&W"
A = chr(39)

def fix(s):
    return s.replace(chr(0x2019), A) if isinstance(s, str) else s

def all_paragraphs(doc):
    for p in doc.paragraphs:
        yield p
    for t in doc.tables:
        for row in t.rows:
            for cell in row.cells:
                for p in cell.paragraphs:
                    yield p

def find_para(doc, key):
    key = fix(key)
    hits = []
    seen = set()
    for p in all_paragraphs(doc):
        if id(p._p) in seen:
            continue
        seen.add(id(p._p))
        if key in p.text:
            hits.append(p)
    if len(hits) != 1:
        raise ValueError("para key %r matched %d" % (key, len(hits)))
    return hits[0]

def sev_label(sev):
    return "Must-have" if sev == "Critical" else "Important but negotiable"

def comment_paras(c):
    out = []
    head = "[%s | %s]" % (c["sev"], sev_label(c["sev"]))
    if c.get("partner"):
        head += " [PARTNER DISCUSSION]"
    out.append(head)
    out.append("(a) Issue: " + fix(c["issue"]))
    out.append("(b) Playbook position: " + fix(c["pb"]))
    out.append("(c) Why needed: " + fix(c["why"]))
    out.append("(d) Classification: %s - %s." % (c["sev"], sev_label(c["sev"])))
    return out

def _style_run(run, kind):
    if kind == "del":
        run.font.strike = True
        run.font.color.rgb = RED
    elif kind == "ins":
        run.font.underline = True
        run.font.color.rgb = RED

def apply_ops(doc, para, ops):
    """ops: list of dict(type=replace|delete|insert|comment, old=..., new=..., anchor=..., c=commentdict)"""
    text = para.text
    runs = list(para.runs)
    # char -> run index map
    owner = []
    for i, r in enumerate(runs):
        owner += [i] * len(r.text)
    assert len(owner) == len(text)
    events = []  # (start, end, newtext, op)
    for op in ops:
        t = op["type"]
        if t in ("replace", "delete", "comment"):
            old = fix(op["old"])
            n = text.count(old)
            occ = op.get("occ", 0)
            if n == 0 or (n > 1 and "occ" not in op):
                raise ValueError("old %r found %d times in para %r" % (old[:60], n, text[:60]))
            start = -1
            for _ in range(occ + 1):
                start = text.find(old, start + 1)
            events.append((start, start + len(old), fix(op.get("new", "")) if t == "replace" else "", op))
        elif t == "insert":
            anc = fix(op["anchor"])
            n = text.count(anc)
            if n != 1:
                raise ValueError("anchor %r found %d times" % (anc[:60], n))
            pos = text.find(anc) + len(anc)
            events.append((pos, pos, fix(op["new"]), op))
        elif t == "insert_start":
            events.append((0, 0, fix(op["new"]), op))
    events.sort(key=lambda e: (e[0], e[1]))
    for a, b in zip(events, events[1:]):
        if a[1] > b[0]:
            raise ValueError("overlap in para %r" % text[:60])
    rprs = [copy.deepcopy(r._r.rPr) if r._r.rPr is not None else None for r in runs]
    for r in runs:
        r._r.getparent().remove(r._r)
    def mk(txt, src, kind):
        nr = para.add_run(txt)
        if src is not None and rprs[src] is not None:
            nr._r.insert(0, copy.deepcopy(rprs[src]))
        _style_run(nr, kind)
        return nr
    def emit_plain(s, e):
        out = []
        i = s
        while i < e:
            j = i
            while j < e and owner[j] == owner[i]:
                j += 1
            out.append(mk(text[i:j], owner[i], None))
            i = j
        return out
    cur = 0
    pending_comments = []
    for (s, e, new, op) in events:
        emit_plain(cur, s)
        made = []
        t = op["type"]
        if t == "comment":
            made += emit_plain(s, e)
        else:
            if e > s:
                i = s
                while i < e:
                    j = i
                    while j < e and owner[j] == owner[i]:
                        j += 1
                    made.append(mk(text[i:j], owner[i], "del"))
                    i = j
            if new:
                src = owner[s - 1] if s > 0 else (owner[0] if owner else None)
                if op.get("plain_src") is not None:
                    src = op["plain_src"]
                made.append(mk(new, src, "ins"))
        cur = e
        if op.get("c"):
            pending_comments.append((made, op["c"]))
    emit_plain(cur, len(text))
    for made, c in pending_comments:
        add_comment(doc, made, c)

def add_comment(doc, runs, c):
    paras = comment_paras(c) if isinstance(c, dict) else [fix(c)]
    cm = doc.add_comment(runs, text=paras[0], author=AUTHOR, initials=INITIALS)
    for ptxt in paras[1:]:
        cm.add_paragraph(ptxt)
    return cm

def insert_para_after(doc, ref_para, segments, c=None):
    """segments: list of (text, bold). Entire paragraph is an insertion."""
    new_p = copy.deepcopy(ref_para._p)
    for child in list(new_p):
        if child.tag != qn("w:pPr"):
            new_p.remove(child)
    ref_para._p.addnext(new_p)
    from docx.text.paragraph import Paragraph
    np_ = Paragraph(new_p, ref_para._parent)
    made = []
    for txt, bold in segments:
        r = np_.add_run(fix(txt))
        r.font.name = "Times New Roman"
        r.bold = bold if bold else None
        _style_run(r, "ins")
        made.append(r)
    if c:
        add_comment(doc, made, c)
    return np_
